// A stand-in for the `postgres` package, for app_usage.py --self-test: answers QUERY_JS's statements from rows.json
// (one workspace, "w1", with three people: one named, one with an email for a name, one not on the roster at all).
// It records every statement and fails the run if one is not read-only or reads without the workspace set.
import fs from 'node:fs';
const R = JSON.parse(fs.readFileSync(new URL('./rows.json', import.meta.url)));
export default function pg() {
  let org = null; const seen = [];
  const t = async (strings, ...vals) => {
    const q = strings.join('?').replace(/\s+/g, ' ');
    if (/\b(insert|update|delete|truncate|alter|drop|create|grant)\b/i.test(q)) throw new Error('write attempted: ' + q);
    if (q.includes("set_config('app.org_id'")) { org = vals[0]; return [{}]; }
    if (q.includes("set_config('statement_timeout'")) return [{}];
    if (q.includes('from pg_roles')) return [{ role: 'app_rw', su: false, bypass: false }];
    if (q.includes('from orgs')) return [{ org_id: 'w1', name: 'Workspace One' }];
    if (org !== 'w1') throw new Error('read without the workspace set: ' + q);
    for (const [needle, rows] of R) if (q.includes(needle)) return rows;
    throw new Error('fixture has no rows for: ' + q);
  };
  return { begin: async (mode, fn) => { if (mode !== 'read only') throw new Error('not read only'); org = null; return fn(t); }, end: async () => {} };
}
